class Component extends DCLogic {
  componentDidMount(){ const go=()=>window.SWD?SWD.ready(()=>this.init()):setTimeout(go,30); go(); }
  componentWillUnmount(){ clearInterval(this.tm); }
  init(){
    const D=SW_DEMO_DATA, CF=SW_DEMO, $=id=>document.getElementById(id), UF=SWD.UFS(), CT=CF.country, Y=CF.YEARS, CY=CF.CENSUS_YEAR;
    SWD.page({active:'idade',lv:'BR',label:'Pirâmide etária'});
    const st={l:SWD.q.get('u')||'BR',y:CY,cmp:'BR',play:false};
    const get=(l,y)=>y===CY?D.pyr[l]:(D.hist[y]&&D.hist[y][l]);
    const srcOf=y=>y===CY?'pyr':y<CY?'pyrH':'proj';
    $('place').innerHTML=`<option value="BR">${CT.name}</option>`+UF.slice().sort((a,b)=>SWD.name(a).localeCompare(SWD.name(b))).map(u=>`<option value="${u}">${SWD.name(u)}</option>`).join('');
    $('place').value=st.l; $('place').onchange=e=>{st.l=e.target.value; draw()};
    SWD.seg($('cmp'),[['BR',`Comparar com ${CT.name}`,`× ${CT.name}`],['none','Sem comparação','Sem']],st.cmp,k=>{st.cmp=k;draw()},'Comparação');
    const yb=$('years');
    yb.innerHTML=Y.map(y=>`<button type="button" data-y="${y}" class="${y>CY?'pj':''}">${y}</button>`).join('');
    yb.onclick=e=>{const b=e.target.closest('button'); if(b){stop(); st.y=+b.dataset.y; draw()}};
    const stop=()=>{st.play=false; clearInterval(this.tm); paintPlay()};
    const paintPlay=()=>{ $('play').innerHTML=st.play?'❚❚ Pausar':'▶ Ver a evolução'; $('play').setAttribute('aria-pressed',st.play); };
    $('play').onclick=()=>{ if(st.play) return stop(); st.play=true; if(st.y===Y[Y.length-1]) st.y=Y[0]; paintPlay(); draw();
      this.tm=setInterval(()=>{ const i=Y.indexOf(st.y); if(i>=Y.length-1) return stop(); st.y=Y[i+1]; draw(); },1300); };
    paintPlay();
    const draw=()=>{ const a=get(st.l,st.y), proj=st.y>CY, nm=SWD.name(st.l), useCmp=st.cmp==='BR'&&st.l!=='BR';
      $('vt').textContent=`${nm}, ${st.y}`;
      $('vs').innerHTML=proj?'Projeção do IBGE. Não é medição.':st.y===CY?'Censo 2022, por sexo e faixa de 5 anos.':`Censo ${st.y}, por sexo e faixa de 5 anos.`;
      $('vstamp').innerHTML=SWD.stamp(srcOf(st.y));
      yb.querySelectorAll('button').forEach(b=>{const on=+b.dataset.y===st.y; b.classList.toggle('on',on); b.setAttribute('aria-pressed',on)});
      if(!a){ $('pyr').innerHTML=SWD.lvbox('sem','Não há pirâmide deste lugar neste ano.'); return; }
      SWD.pyramid($('pyr'),{a,cmp:useCmp?get('BR',st.y):null,cmpLabel:CT.name,proj,W:720,H:540,max:7,aria:`Pirâmide etária de ${nm}, ${st.y}`});
      $('lg').innerHTML=`<span><i style="background:var(--sx-m)${proj?';opacity:.55':''}"></i>Homens</span><span><i style="background:var(--sx-f)${proj?';opacity:.55':''}"></i>Mulheres</span>${useCmp?`<span><i class="ln"></i>${CT.name} no mesmo ano</span>`:''}<span style="color:var(--faint)">% da população total em cada faixa</span>`;
      const s=SWD.ageStats(a), f=(l,v,sub)=>`<div class="oth"><div class="t">${l}</div><div class="v"><b>${v}</b>${sub?`<span>${sub}</span>`:''}</div></div>`;
      $('ah').textContent=`${nm}, ${st.y}`;
      $('facts').innerHTML=f('Idade mediana',`${SWD.num(s.med,1)} anos`,'metade tem menos que isso')+f('Índice de envelhecimento',SWD.num(s.envel,1),'pessoas de 65 anos ou mais para cada 100 de 0 a 14')+f('Crianças, 0 a 14 anos',SWD.pct(s.kids))+f('Pessoas de 65 anos ou mais',SWD.pct(s.old))+`<div style="padding-top:10px">${SWD.stamp(srcOf(st.y))}</div>`;
      const pts=Y.map(y=>{const p=get(st.l,y); return p?[y,SWD.ageStats(p).med]:null}).filter(Boolean);
      SWD.lines($('med'),{series:[{name:'Censo',nolabel:true,pts:pts.filter(p=>p[0]<=CY),c:'var(--accent)',dots:true},{name:'Projeção',pts:pts.filter(p=>p[0]>=CY),c:'var(--accent)',dash:true}],W:380,H:200,R:80,fmt:v=>SWD.num(v,0)+' anos',xs:[1980,2022,2060],aria:`Idade mediana de ${nm}`});
      $('src').innerHTML=SWD.srcLine(['pyrH','pyr','proj'])+' Idade mediana e índice calculados pelo StatWorld sobre as faixas de 5 anos.';
    };
    draw();
  }
  renderVals(){ return {}; }
}
